-- ROLLBACK: put the engineering homepage back to the 2026-10-08 before-state
-- Engineering Supabase project (engg.jkkn.ac.in). DEP-47, 2026-10-08.
-- Every UPDATE is guarded by the value it expects to replace. If any guard misses,
-- the whole transaction is rolled back and nothing changes.
BEGIN;
DO $do$
DECLARE n int; pid uuid;
BEGIN
  -- EngineeringHeroSection (sort_order 0)
  UPDATE cms_page_blocks SET props = $j${"badge": "AICTE Approved | Anna University Affiliated | NAAC Accredited", "stats": [{"icon": "graduation", "label": "Learners", "value": 3000, "suffix": "+"}, {"icon": "trending", "label": "Placement", "value": 95, "suffix": "%"}, {"icon": "building", "label": "Top Recruiters", "value": 6, "suffix": ""}, {"icon": "users", "label": "Programs", "value": 12, "suffix": "+"}], "title": "Shape Your Future in Engineering & Technology", "subtitle": "AICTE Approved | Anna University Affiliated | NAAC Accredited", "heroImage": "https://kyvfkyjmdbtyimtedkie.supabase.co/storage/v1/object/public/media/general/1887a999-7302-4eeb-be9c-8e9095cb274d.JPG", "primaryCta": {"link": "https://www.jkkn.ai/apply/jkkn-admission-2026", "label": "Apply Now"}, "accentColor": "#ffde59", "description": "Join one of the leading engineering colleges with 70+ years of educational excellence. World-class senior learners, state-of-the-art infrastructure, and 95% placement record.", "primaryColor": "#0b6d41", "secondaryCta": {"link": "#programs", "label": "Explore Programs"}, "showAnimations": true}$j$::jsonb
   WHERE id = 'e2e248bf-97d0-465c-a527-ad8729a3ce05' AND props = $j${"badge": "AICTE Approved | Autonomous | Anna University Affiliated | NAAC Accredited", "stats": [{"icon": "graduation", "label": "Learners", "value": 3000, "suffix": "+"}, {"icon": "trending", "label": "Placement", "value": 95, "suffix": "%"}, {"icon": "building", "label": "Top Recruiters", "value": 6, "suffix": ""}, {"icon": "users", "label": "Programs", "value": 12, "suffix": "+"}], "title": "Shape Your Future in Engineering & Technology", "subtitle": "AICTE Approved | Autonomous | Anna University Affiliated | NAAC Accredited", "heroImage": "https://kyvfkyjmdbtyimtedkie.supabase.co/storage/v1/object/public/media/general/1887a999-7302-4eeb-be9c-8e9095cb274d.JPG", "primaryCta": {"link": "https://www.jkkn.ai/apply/jkkn-admission-2026", "label": "Apply Now"}, "accentColor": "#ffde59", "description": "Join JKKN College of Engineering and Technology (Autonomous), Komarapalayam - AICTE approved and affiliated to Anna University, Chennai.", "primaryColor": "#0b6d41", "secondaryCta": {"link": "#programs", "label": "Explore Programs"}, "showAnimations": true}$j$::jsonb;
  GET DIAGNOSTICS n = ROW_COUNT;
