  -- EngineeringAccreditationsBar (sort_order 1)
  UPDATE cms_page_blocks SET props = $j${"label": "Recognized & Approved By", "paddingY": "md", "primaryColor": "#0b6d41", "accreditations": [{"icon": "shield", "logo": "https://kyvfkyjmdbtyimtedkie.supabase.co/storage/v1/object/public/media/general/cbc3b531-4675-4aff-9534-e97910548f3a.png", "name": "All India Council for Technical Education", "shortName": "AICTE", "description": "Approved"}, {"icon": "graduation", "logo": "https://kyvfkyjmdbtyimtedkie.supabase.co/storage/v1/object/public/media/general/42e53c74-88ff-41e2-9392-71883f154694.png", "name": "Anna University", "shortName": "Anna University", "description": "Affiliated"}, {"icon": "award", "name": "National Board of Accreditation", "shortName": "NAAC", "description": "Accredited"}], "showAnimations": true, "backgroundColor": "#f8f9fa"}$j$::jsonb
   WHERE id = '92ac1648-2738-45f9-96b3-baf066f08af7' AND props = $j${"label": "Recognized & Approved By", "paddingY": "md", "primaryColor": "#0b6d41", "accreditations": [{"icon": "shield", "logo": "https://kyvfkyjmdbtyimtedkie.supabase.co/storage/v1/object/public/media/general/cbc3b531-4675-4aff-9534-e97910548f3a.png", "name": "All India Council for Technical Education", "shortName": "AICTE", "description": "Approved"}, {"icon": "graduation", "logo": "https://kyvfkyjmdbtyimtedkie.supabase.co/storage/v1/object/public/media/general/42e53c74-88ff-41e2-9392-71883f154694.png", "name": "Anna University", "shortName": "Anna University", "description": "Affiliated"}, {"icon": "award", "name": "National Board of Accreditation", "shortName": "NAAC", "description": "Accredited"}, {"icon": "award", "name": "University Grants Commission", "shortName": "UGC", "description": "Autonomous Status"}], "showAnimations": true, "backgroundColor": "#f8f9fa"}$j$::jsonb;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'EngineeringAccreditationsBar: expected 1 row, got %', n; END IF;
  -- EngineeringAboutSection (sort_order 2)
  UPDATE cms_page_blocks SET props = $j${"cta": {"link": "/our-institutions", "label": "Learn More About Us"}, "badge": {"text": "70 Years Legacy", "position": "top-left"}, "image": "https://kyvfkyjmdbtyimtedkie.supabase.co/storage/v1/object/public/media/general/1887a999-7302-4eeb-be9c-8e9095cb274d.JPG", "title": "Welcome to JKKN College of Engineering", "features": ["AICTE Approved & Anna University Affiliated", "NAAC Accredited Programs", "Industry-Academia Partnerships", "State-of-the-Art Learning Learning Labs", "95% Placement Record", "Experienced Senior Learners"], "imageAlt": "JKKN Engineering College Campus", "paddingY": "lg", "subtitle": "About Us", "accentColor": "#ffde59", "description": "Established as part of the prestigious JKKN Institutions with over 70 years of legacy, JKKN College of Engineering is committed to producing industry-ready engineers through quality education, practical training, and holistic development. Our state-of-the-art infrastructure and experienced senior learners ensure learners receive world-class technical education.", "primaryColor": "#0b6d41", "imagePosition": "left", "showAnimations": true, "backgroundColor": "#ffffff"}$j$::jsonb
   WHERE id = '8ec50a7d-d4b3-4955-bacf-6314fa70951a' AND props = $j${"cta": {"link": "/our-institutions", "label": "Learn More About Us"}, "badge": {"text": "70 Years Legacy", "position": "top-left"}, "image": "https://kyvfkyjmdbtyimtedkie.supabase.co/storage/v1/object/public/media/general/1887a999-7302-4eeb-be9c-8e9095cb274d.JPG", "title": "Welcome to JKKN College of Engineering and Technology (Autonomous)", "features": ["AICTE Approved, Autonomous & Anna University Affiliated", "NAAC Accredited Programs", "Industry-Academia Partnerships", "State-of-the-Art Learning Learning Labs", "95% Placement Record", "Experienced Senior Learners"], "imageAlt": "JKKN Engineering College Campus", "paddingY": "lg", "subtitle": "About Us", "accentColor": "#ffde59", "description": "Established as part of the prestigious JKKN Institutions with over 70 years of legacy, JKKN College of Engineering is committed to producing industry-ready engineers through quality education, practical training, and holistic development. Our state-of-the-art infrastructure and experienced senior learners ensure learners receive world-class technical education. The college is an autonomous institution: autonomous status has been conferred by UGC, New Delhi and Anna University, Chennai.", "primaryColor": "#0b6d41", "imagePosition": "left", "showAnimations": true, "backgroundColor": "#ffffff"}$j$::jsonb;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'EngineeringAboutSection: expected 1 row, got %', n; END IF;
  -- EngineeringWhyChooseSection (sort_order 4)
  UPDATE cms_page_blocks SET props = $j${"title": "Why Choose JKKN Engineering College?", "columns": "4", "features": [{"icon": "award", "title": "70 Years Legacy", "description": "Part of JKKN Institutions with seven decades of excellence in education"}, {"icon": "building", "title": "Industry Connect", "description": "Strong partnerships with leading IT and core industry companies"}, {"icon": "graduation", "title": "Expert Learning Facilitators", "description": "Highly qualified senior learners with industry experience and research background"}, {"icon": "flask", "title": "Modern Learning Labs & Infrastructure", "description": "State-of-the-art learning learning labs equipped with latest technology"}, {"icon": "trending", "title": "95% Placements", "description": "Consistently high placement rate with top recruiters visiting campus"}, {"icon": "lightbulb", "title": "Innovation Hub", "description": "Dedicated centers for AI, ML, IoT, and emerging technologies"}, {"icon": "globe", "title": "Global Exposure", "description": "International collaborations and learner exchange programs"}, {"icon": "home", "title": "Excellent Hostel Facilities", "description": "Separate hostels for boys and girls with modern amenities"}], "paddingY": "lg", "subtitle": "Your Gateway to a Successful Engineering Career", "accentColor": "#ffde59", "primaryColor": "#0b6d41", "showAnimations": true, "backgroundColor": "#fbfbee"}$j$::jsonb
   WHERE id = '82afebc7-84d6-428b-a3ec-6b53b9498186' AND props = $j${"title": "Why Choose JKKN Engineering College?", "columns": "4", "features": [{"icon": "award", "title": "70 Years Legacy", "description": "Part of JKKN Institutions with seven decades of excellence in education"}, {"icon": "building", "title": "Industry Connect", "description": "Strong partnerships with leading IT and core industry companies"}, {"icon": "graduation", "title": "Expert Learning Facilitators", "description": "Highly qualified senior learners with industry experience and research background"}, {"icon": "flask", "title": "Modern Learning Labs & Infrastructure", "description": "State-of-the-art learning learning labs equipped with latest technology"}, {"icon": "award", "title": "Autonomous Institution", "description": "Autonomous status conferred by UGC, New Delhi and Anna University, Chennai"}, {"icon": "lightbulb", "title": "Innovation Hub", "description": "Dedicated centers for AI, ML, IoT, and emerging technologies"}, {"icon": "globe", "title": "Global Exposure", "description": "International collaborations and learner exchange programs"}, {"icon": "home", "title": "Excellent Hostel Facilities", "description": "Separate hostels for boys and girls with modern amenities"}], "paddingY": "lg", "subtitle": "Your Gateway to a Successful Engineering Career", "accentColor": "#ffde59", "primaryColor": "#0b6d41", "showAnimations": true, "backgroundColor": "#fbfbee"}$j$::jsonb;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'EngineeringWhyChooseSection: expected 1 row, got %', n; END IF;
  -- FAQAccordion (sort_order 9)
  UPDATE cms_page_blocks SET props = $j${"faqs": [{"answer": "We offer B.E. programs in Computer Science & Engineering, Electronics & Communication, Electrical & Electronics, Mechanical Engineering, and Civil Engineering. We also offer B.Tech programs in AI & Machine Learning and Information Technology, along with postgraduate programs MBA and MCA.", "question": "What engineering courses are offered at JKKN Engineering College?"}, {"answer": "Yes, JKKN College of Engineering & Technology is approved by AICTE (All India Council for Technical Education), affiliated with Anna University, and has NAAC accreditation for multiple programs. We are also NAAC accredited with A+ grade and ISO 9001:2015 certified.", "question": "Is JKKN Engineering College AICTE approved?"}, {"answer": "Admission to B.E./B.Tech programs is through TNEA counselling or direct admission. Eligibility requires passing 10+2 with Physics, Chemistry, and Mathematics with minimum 45% aggregate marks. Fill out the online application, submit documents, attend counselling, pay fees, and complete enrollment.", "question": "What is the admission process for B.E./B.Tech programs?"}, {"answer": "We maintain an excellent placement record with 95%+ placement rate. The highest package offered is 12 LPA with an average package of 4.5 LPA. Over 50 companies recruit from our campus including TCS, Infosys, Wipro, Cognizant, IBM, Amazon, Zoho, and more.", "question": "What is the placement record at JKKN Engineering College?"}, {"answer": "We provide state-of-the-art facilities including 500+ computer systems in modern learning labs, engineering workshops, research learning labs for AI/ML/IoT/Robotics, digital library with 50,000+ books, Wi-Fi campus, separate hostels for boys and girls, cafeteria, sports complex, and transportation services.", "question": "What facilities are available for learners?"}, {"answer": "Yes, we offer a dedicated B.Tech program in Artificial Intelligence & Machine Learning with 60 seats. The program covers Deep Learning, Neural Networks, Data Science, and cutting-edge AI technologies with hands-on projects and industry internships.", "question": "Does JKKN offer AI and Machine Learning courses?"}, {"answer": "The fee structure varies by program and category. Please visit our admissions page or contact the admission office for detailed fee information. We also offer scholarships for meritorious learners and fee concessions for economically weaker sections.", "question": "What is the fee structure for engineering programs?"}, {"answer": "Yes, we provide separate hostel facilities for boys and girls within the campus. Hostels are equipped with furnished rooms, 24/7 security, WiFi connectivity, recreational areas, mess facilities with hygienic food, and medical support.", "question": "Is hostel accommodation available?"}], "allowMultiple": false, "searchEnabled": false}$j$::jsonb
   WHERE id = 'c580992b-3dcb-4d50-a31b-84c97f009f4f' AND props = $j${"faqs": [{"answer": "We offer B.E. programs in Computer Science & Engineering, Electronics & Communication, Electrical & Electronics, Mechanical Engineering, and Civil Engineering. We also offer B.Tech programs in AI & Machine Learning and Information Technology, along with postgraduate programs MBA and MCA.", "question": "What engineering courses are offered at JKKN Engineering College?"}, {"answer": "Yes. JKKN College of Engineering and Technology is approved by AICTE (All India Council for Technical Education) and affiliated to Anna University, Chennai. It is an autonomous institution, with autonomous status conferred by UGC, New Delhi and Anna University, Chennai, and it is NAAC accredited.", "question": "Is JKKN Engineering College AICTE approved?"}, {"answer": "Yes. JKKN College of Engineering and Technology (JKKNCET), Komarapalayam, is an autonomous institution: autonomous status has been conferred by UGC, New Delhi and Anna University, Chennai. The college remains affiliated to Anna University, Chennai, and is approved by AICTE for its B.E., B.Tech, M.E. and MBA programmes.", "question": "Is JKKN College of Engineering and Technology an autonomous college?"}, {"answer": "Admission to B.E./B.Tech programs is through TNEA counselling or direct admission. Eligibility requires passing 10+2 with Physics, Chemistry, and Mathematics with minimum 45% aggregate marks. Fill out the online application, submit documents, attend counselling, pay fees, and complete enrollment.", "question": "What is the admission process for B.E./B.Tech programs?"}, {"answer": "We maintain an excellent placement record with 95%+ placement rate. The highest package offered is 12 LPA with an average package of 4.5 LPA. Over 50 companies recruit from our campus including TCS, Infosys, Wipro, Cognizant, IBM, Amazon, Zoho, and more.", "question": "What is the placement record at JKKN Engineering College?"}, {"answer": "We provide state-of-the-art facilities including 500+ computer systems in modern learning labs, engineering workshops, research learning labs for AI/ML/IoT/Robotics, digital library with 50,000+ books, Wi-Fi campus, separate hostels for boys and girls, cafeteria, sports complex, and transportation services.", "question": "What facilities are available for learners?"}, {"answer": "Yes, we offer a dedicated B.Tech program in Artificial Intelligence & Machine Learning with 60 seats. The program covers Deep Learning, Neural Networks, Data Science, and cutting-edge AI technologies with hands-on projects and industry internships.", "question": "Does JKKN offer AI and Machine Learning courses?"}, {"answer": "The fee structure varies by program and category. Please visit our admissions page or contact the admission office for detailed fee information. We also offer scholarships for meritorious learners and fee concessions for economically weaker sections.", "question": "What is the fee structure for engineering programs?"}, {"answer": "Yes, we provide separate hostel facilities for boys and girls within the campus. Hostels are equipped with furnished rooms, 24/7 security, WiFi connectivity, recreational areas, mess facilities with hygienic food, and medical support.", "question": "Is hostel accommodation available?"}], "allowMultiple": false, "searchEnabled": false}$j$::jsonb;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'FAQAccordion: expected 1 row, got %', n; END IF;
  -- EngineeringCTASection (sort_order 10)
  UPDATE cms_page_blocks SET props = $j${"title": "Ready to Engineer Your Future?", "paddingY": "lg", "subtitle": "Join JKKN College of Engineering and take the first step towards a successful career in technology", "showEmail": false, "showPhone": true, "primaryCta": {"link": "https://www.jkkn.ai/apply/jkkn-admission-2026", "label": "Apply Now"}, "accentColor": "#ffde59", "phoneNumber": "+91 9345855001", "primaryColor": "#0b6d41", "showAnimations": true}$j$::jsonb
   WHERE id = 'f1cf62c6-e710-40b1-a336-5edf99100344' AND props = $j${"title": "Ready to Engineer Your Future?", "paddingY": "lg", "subtitle": "Join JKKN College of Engineering and Technology (Autonomous) and take the first step towards a successful career in technology", "showEmail": false, "showPhone": true, "primaryCta": {"link": "https://www.jkkn.ai/apply/jkkn-admission-2026", "label": "Apply Now"}, "accentColor": "#ffde59", "phoneNumber": "+91 9345855001", "primaryColor": "#0b6d41", "showAnimations": true}$j$::jsonb;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'EngineeringCTASection: expected 1 row, got %', n; END IF;
  -- Google description and share text of the homepage
  SELECT page_id INTO pid FROM cms_page_blocks WHERE id = 'e2e248bf-97d0-465c-a527-ad8729a3ce05';
  UPDATE cms_seo_metadata SET meta_description = $t$JKKNCET — one of the best private engineering colleges in Tamilnadu. A top engineering college with NAAC accreditation, excellent placements & affordable fees.$t$,
         og_description = CASE WHEN og_description = $t$JKKNCET (Autonomous) — one of the best private engineering colleges in Tamilnadu. AICTE approved, affiliated to Anna University, Chennai, and NAAC accredited.$t$ THEN $t$JKKNCET — one of the best private engineering colleges in Tamilnadu. A top engineering college with NAAC accreditation, excellent placements & affordable fees.$t$ ELSE og_description END,
         twitter_description = CASE WHEN twitter_description = $t$JKKNCET (Autonomous) — one of the best private engineering colleges in Tamilnadu. AICTE approved, affiliated to Anna University, Chennai, and NAAC accredited.$t$ THEN $t$JKKNCET — one of the best private engineering colleges in Tamilnadu. A top engineering college with NAAC accreditation, excellent placements & affordable fees.$t$ ELSE twitter_description END
   WHERE page_id = pid AND meta_description = $t$JKKNCET (Autonomous) — one of the best private engineering colleges in Tamilnadu. AICTE approved, affiliated to Anna University, Chennai, and NAAC accredited.$t$;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'homepage SEO row: expected 1 row, got %', n; END IF;
  -- header logo alt text (site_settings.setting_value is jsonb)
  UPDATE site_settings SET setting_value = to_jsonb($t$JKKN Engineering College$t$::text)
   WHERE setting_key = 'logo_alt_text' AND setting_value = to_jsonb($t$JKKN College of Engineering and Technology (Autonomous)$t$::text);
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'logo_alt_text: expected 1 row, got %', n; END IF;
END $do$;
COMMIT;
